yotsuba.css:
a, a:visited {
	color: #00E;
	text-decoration: none;
}
a:hover {
	color: red !important;
}
body { color: #800000; font-family: arial, helvetica, sans-serif; font-size: 10pt; }
.postblock {
	background-color: #EA8;
	color: #800;
	font-weight: bold;
	border: 1px solid #800;
	padding: 0 5px;
	font-size: 10pt;
}
.highlightPost:not(.op) {
	background: #f0d6d6 !important;
	border-color: #d69595 !important;
}
table.flashListing td.postblock {
	padding: 5px;
	text-align: center;
}
table.flashListing td {
	padding: 2px;
	font-size: 9pt;
}
table.flashListing td:not(.subject) {
	text-align: center;
}
table.flashListing .name {
	color: #117743;
	font-weight: bold;
}
table.flashListing .postertrip {
	color: #117743;
}
table.flashListing .subject {
	color: #cc1105;
	font-weight: bold;
}
table.flashListing tr:nth-of-type(odd) {
	background-color: #ede2d4;
}
.name-col, .file-col, table.flashListing .subject {
  max-width: 250px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  word-wrap: break-word;
}

